-- ===========================================================================
-- The Dominion of Una Court - English localization
-- ===========================================================================

INSERT INTO Language_en_US (Tag, Text) VALUES
('TXT_KEY_TRAIT_DOMINION_ONE_WHO_POSSESSES', 'The One Who Possesses Una Court'),
('TXT_KEY_TRAIT_DOMINION_ONE_WHO_POSSESSES_SHORT', 'The One Who Possesses Una Court'),
('TXT_KEY_TRAIT_DOMINION_ONE_WHO_POSSESSES_HELP', 'While Trentrouls lives, all cities gain +1% to all yields and Great Person generation per Era. The bonus doubles during Body Swap, which also grants Golden Age Points. If Trentrouls dies, the Dominion collapses.'),

('TXT_KEY_LEADER_DOMINION_TRENTROULS', 'Trentrouls'),
('TXT_KEY_LEADER_DOMINION_TRENTROULS_PEDIA', 'Supreme Possessor Trentrouls rules the Dominion of Una Court through conquest, stolen bodies, and the certainty that his original flesh is inseparable from the state. Every exchange places that irreplaceable body in enemy hands, turning each triumph into a calculated mortal risk.'),
('TXT_KEY_CIVILOPEDIA_LEADERS_DOMINION_TRENTROULS', 'Trentrouls, Supreme Possessor'),

('TXT_KEY_CIV_DOMINION_UNA_COURT_DESC', 'The Dominion of Una Court'),
('TXT_KEY_CIV_DOMINION_UNA_COURT_SHORT_DESC', 'Dominion of Una Court'),
('TXT_KEY_CIV_DOMINION_UNA_COURT_ADJECTIVE', 'Dominion'),
('TXT_KEY_CIV_DOMINION_UNA_COURT_PEDIA', 'The Dominion of Una Court is the aggressive reflection of the Freehold. Its Supreme Possessor enters enemy bodies while hostile hands receive his original form. During every Body Swap, the Dominion prospers and gathers Golden Age momentum, but the death of Trentrouls'' original body destroys the realm. Centrelink remains the shared institution of both Una Courts.'),
('TXT_KEY_CIV_DOMINION_UNA_COURT_STRATEGY', 'Advance Trentrouls close enough to seize a valuable enemy body, then exploit its movement, attacks, founding, construction, religious, or Great Person actions. Body Swap doubles the era-scaled empire bonus and grants Golden Age Points, but the enemy receives Trentrouls'' original body until the swap ends. Guard its position carefully.'),
('TXT_KEY_CIV5_DOMINION_UNA_COURT_HEADING_1', 'The Dominion'),
('TXT_KEY_CIV5_DOMINION_UNA_COURT_TEXT_1', 'The Dominion treats identity as territory. Its armies advance not merely to defeat an enemy, but to turn the enemy''s own strength into the instrument of conquest.'),
('TXT_KEY_CIV5_DOMINION_UNA_COURT_HEADING_2', 'The Supreme Possessor'),
('TXT_KEY_CIV5_DOMINION_UNA_COURT_TEXT_2', 'Trentrouls can exchange bodies with an enemy nearby. The Dominion gains the borrowed vessel, while the enemy receives the one life on which Una Court depends.'),
('TXT_KEY_CIV5_DOMINION_UNA_COURT_HEADING_3', 'Strategy'),
('TXT_KEY_CIV5_DOMINION_UNA_COURT_TEXT_3', 'Choose bodies whose actions can permanently alter the war. A Settler can found for the Dominion and a Great Person can be expended, but every swap gives the enemy a chance to kill Trentrouls and end the campaign.'),
('TXT_KEY_CIV5_DOM_DOMINION_UNA_COURT_TEXT', 'Supreme Possessor Trentrouls, the Dominion gathers beneath the certainty of your will.[NEWLINE][NEWLINE]Its cities prosper while your original body lives, and every stolen vessel promises an age of conquest. Even Centrelink, shared with the gentler Freehold, now sustains expansion beneath a red standard.[NEWLINE][NEWLINE]Take the bodies of those who oppose you, turn their strength against them, and accept the absolute wager at the heart of your reign: should your first body fall, the Dominion falls with it.'),

('TXT_KEY_CITY_NAME_DOMINION_SEIZED_BODY', 'Seized Body'),
('TXT_KEY_CITY_NAME_DOMINION_RED_COURT', 'The Red Court'),
('TXT_KEY_CITY_NAME_DOMINION_IRON_WILL', 'Iron Will'),
('TXT_KEY_CITY_NAME_DOMINION_LAST_BODY', 'The Last Body'),
('TXT_KEY_CITY_NAME_DOMINION_POSSESSORS_REST', 'Possessor''s Rest'),
('TXT_KEY_CITY_NAME_DOMINION_CONQUEST', 'Conquest'),
('TXT_KEY_SPY_NAME_DOMINION_VESSEL', 'The Vessel'),
('TXT_KEY_SPY_NAME_DOMINION_WITNESS', 'The Witness'),
('TXT_KEY_SPY_NAME_DOMINION_USURPER', 'The Usurper'),

('TXT_KEY_UNIT_DOMINION_TRENTROULS', 'Trentrouls'),
('TXT_KEY_UNIT_DOMINION_TRENTROULS_HELP', 'Irreplaceable Dominion hero with Era-scaled Combat Strength. May Body Swap with an eligible enemy within 2 tiles. The Dominion receives the borrowed body and doubled city bonuses while the enemy controls Trentrouls'' original body. His death eliminates the Dominion.'),
('TXT_KEY_UNIT_DOMINION_TRENTROULS_STRATEGY', 'Use Body Swap to steal technologically advanced or strategically valuable units. The borrowed body receives +5% Combat Strength, but exposing Trentrouls'' original body to enemy control can end the game immediately. Saving safely ends an active Body Swap and returns both bodies to their normal owners.'),
('TXT_KEY_UNIT_DOMINION_TRENTROULS_PEDIA', 'The Supreme Possessor begins in his original body and can never be replaced. His Combat Strength rises from 8 in the Ancient Era to 72 in the Information Era. He has no upgrade route and receives no upgrade from Ancient Ruins.'),

('TXT_KEY_PROMOTION_DOMINION_ONE_TRUE_RULER', 'Original Body of the Supreme Possessor'),
('TXT_KEY_PROMOTION_DOMINION_ONE_TRUE_RULER_HELP', 'Cannot be captured or replaced. If this body dies, the Dominion of Una Court collapses.'),
('TXT_KEY_PROMOTION_DOMINION_BORROWED_BODY', 'Borrowed Body'),
('TXT_KEY_PROMOTION_DOMINION_BORROWED_BODY_HELP', '+5% Combat Strength. Controlled by the Dominion until Body Swap ends; actions taken are permanent.'),
('TXT_KEY_PROMOTION_DOMINION_ENEMY_IN_TRENT', 'Enemy in Trentrouls'' Body'),
('TXT_KEY_PROMOTION_DOMINION_ENEMY_IN_TRENT_HELP', 'Temporarily controlled by the target''s owner. Limited to one tile of movement or one melee attack per turn.'),
('TXT_KEY_PROMOTION_DOMINION_SWAP_READY', 'Body Swap: Ready'),
('TXT_KEY_PROMOTION_DOMINION_SWAP_READY_HELP', 'May exchange bodies with one eligible enemy unit within 2 tiles.'),
('TXT_KEY_PROMOTION_DOMINION_SWAP_COOLDOWN', 'Body Swap: Recharging'),
('TXT_KEY_PROMOTION_DOMINION_SWAP_COOLDOWN_HELP', 'Body Swap is active or on cooldown.'),
('TXT_KEY_PROMOTION_DOMINION_SWAP_IMMUNE', 'Immune to Body Swap'),
('TXT_KEY_PROMOTION_DOMINION_SWAP_IMMUNE_HELP', 'This unit cannot be selected as a Body Swap target.'),
('TXT_KEY_PROMOTION_DOMINION_ERA_STRENGTH', 'Supreme Possessor Era Strength'),
('TXT_KEY_PROMOTION_DOMINION_ERA_STRENGTH_HELP', 'Trentrouls'' Combat Strength scales with the Dominion''s current Era.');
